<?php
 namespace Slim; class Route { protected $pattern; protected $callable; protected $conditions = array(); protected static $defaultConditions = array(); protected $name; protected $params = array(); protected $paramNames = array(); protected $paramNamesPath = array(); protected $methods = array(); protected $middleware = array(); protected $caseSensitive; public function __construct($pattern, $callable, $caseSensitive = true) { $this->setPattern($pattern); $this->setCallable($callable); $this->setConditions(self::getDefaultConditions()); $this->caseSensitive = $caseSensitive; } public static function setDefaultConditions(array $defaultConditions) { self::$defaultConditions = $defaultConditions; } public static function getDefaultConditions() { return self::$defaultConditions; } public function getPattern() { return $this->pattern; } public function setPattern($pattern) { $this->pattern = $pattern; } public function getCallable() { return $this->callable; } public function setCallable($callable) { $matches = array(); if (is_string($callable) && preg_match('!^([^\:]+)\:([a-zA-Z_\x7f-\xff][a-zA-Z0-9_\x7f-\xff]*)$!', $callable, $matches)) { $class = $matches[1]; $method = $matches[2]; $callable = function() use ($class, $method) { static $obj = null; if ($obj === null) { $obj = new $class; } return call_user_func_array(array($obj, $method), func_get_args()); }; } if (!is_callable($callable)) { throw new \InvalidArgumentException('Route callable must be callable'); } $this->callable = $callable; } public function getConditions() { return $this->conditions; } public function setConditions(array $conditions) { $this->conditions = $conditions; } public function getName() { return $this->name; } public function setName($name) { $this->name = (string)$name; } public function getParams() { return $this->params; } public function setParams($params) { $this->params = $params; } public function getParam($index) { if (!isset($this->params[$index])) { throw new \InvalidArgumentException('Route parameter does not exist at specified index'); } return $this->params[$index]; } public function setParam($index, $value) { if (!isset($this->params[$index])) { throw new \InvalidArgumentException('Route parameter does not exist at specified index'); } $this->params[$index] = $value; } public function setHttpMethods() { $args = func_get_args(); $this->methods = $args; } public function getHttpMethods() { return $this->methods; } public function appendHttpMethods() { $args = func_get_args(); if(count($args) && is_array($args[0])){ $args = $args[0]; } $this->methods = array_merge($this->methods, $args); } public function via() { $args = func_get_args(); if(count($args) && is_array($args[0])){ $args = $args[0]; } $this->methods = array_merge($this->methods, $args); return $this; } public function supportsHttpMethod($method) { return in_array($method, $this->methods); } public function getMiddleware() { return $this->middleware; } public function setMiddleware($middleware) { if (is_callable($middleware)) { $this->middleware[] = $middleware; } elseif (is_array($middleware)) { foreach ($middleware as $callable) { if (!is_callable($callable)) { throw new \InvalidArgumentException('All Route middleware must be callable'); } } $this->middleware = array_merge($this->middleware, $middleware); } else { throw new \InvalidArgumentException('Route middleware must be callable or an array of callables'); } return $this; } public function matches($resourceUri) { $patternAsRegex = preg_replace_callback( '#:([\w]+)\+?#', array($this, 'matchesCallback'), str_replace(')', ')?', (string)$this->pattern) ); if (substr($this->pattern, -1) === '/') { $patternAsRegex .= '?'; } $regex = '#^' . $patternAsRegex . '$#'; if ($this->caseSensitive === false) { $regex .= 'i'; } if (!preg_match($regex, $resourceUri, $paramValues)) { return false; } foreach ($this->paramNames as $name) { if (isset($paramValues[$name])) { if (isset($this->paramNamesPath[$name])) { $this->params[$name] = safe_explode('/', urldecode($paramValues[$name])); } else { $this->params[$name] = urldecode($paramValues[$name]); } } } return true; } protected function matchesCallback($m) { $this->paramNames[] = $m[1]; if (isset($this->conditions[$m[1]])) { return '(?P<' . $m[1] . '>' . $this->conditions[$m[1]] . ')'; } if (substr($m[0], -1) === '+') { $this->paramNamesPath[$m[1]] = 1; return '(?P<' . $m[1] . '>.+)'; } return '(?P<' . $m[1] . '>[^/]+)'; } public function name($name) { $this->setName($name); return $this; } public function conditions(array $conditions) { $this->conditions = array_merge($this->conditions, $conditions); return $this; } public function dispatch() { foreach ($this->middleware as $mw) { call_user_func_array($mw, array($this)); } $return = call_user_func_array($this->getCallable(), array_values($this->getParams())); return ($return === false) ? false : true; } } 